"""Controller for VLABench book_rearrange instance i00.
All robot I/O uses the standard RCB client; no simulator internals are accessed.
"""
import json
import numpy as np
from rcb_client import Robot

CAMERAS = ["forward", "left", "right", "wrist"]
DT = 0.1

def connect():
    return Robot()

def state(robot):
    return robot.status()

def read_proprio(robot):
    p = robot.get_obs(cameras=[], video="none").meta["proprio"]
    return dict(zip(p["layout"], p["now"]))

def observe(robot, cameras=CAMERAS, depth=False):
    return robot.get_obs(cameras=cameras, include_depth=depth, video="frames")

def q_and_fingers(p):
    q = np.array([p[f"joint{i}_pos"] for i in range(1, 8)], dtype=float)
    f = np.array([p["finger1_pos"], p["finger2_pos"]], dtype=float)
    return q, f

def action_row(q, fingers):
    return np.r_[np.asarray(q, float).reshape(7), np.repeat(float(fingers), 2)]

def move_joints(robot, q, steps, fingers=0.04, note=""):
    row = action_row(q, fingers)
    return robot.submit("joint_position", np.tile(row, (int(steps), 1)), dt=DT,
                        interpolate="linear", cameras=[], video="none", note=note)

def quat_mul(a, b):
    aw, ax, ay, az = a; bw, bx, by, bz = b
    return np.array([aw*bw-ax*bx-ay*by-az*bz,
                     aw*bx+ax*bw+ay*bz-az*by,
                     aw*by-ax*bz+ay*bw+az*bx,
                     aw*bz+ax*by-ay*bx+az*bw])

def quat_inv(q):
    return np.array([q[0], -q[1], -q[2], -q[3]]) / np.dot(q, q)

def quat_rotvec(q):
    q = np.asarray(q, float); q /= np.linalg.norm(q)
    if q[0] < 0: q = -q
    s = np.linalg.norm(q[1:])
    if s < 1e-10: return 2*q[1:]
    return q[1:] * (2*np.arctan2(s, q[0])/s)

def tcp_pose(p):
    xyz = np.array([p[f"tcp_{a}"] for a in "xyz"], float)
    quat = np.array([p[f"tcp_q{a}"] for a in "wxyz"], float)
    return xyz, quat

def estimate_jacobian(robot, epsilon=0.035, steps=4):
    """Measure world TCP translation and rotation response to each joint."""
    limits = np.asarray(robot.spec()["action_types"]["joint_position"]["panda_joint_limits_rad"], float)
    p0 = read_proprio(robot); q0, fingers = q_and_fingers(p0); x0, rot0 = tcp_pose(p0)
    J = np.zeros((6, 7))
    for i in range(7):
        q1 = q0.copy(); q1[i] = np.clip(q1[i]+epsilon, limits[i,0]+1e-4, limits[i,1]-1e-4)
        move_joints(robot, q1, steps, fingers[0], note=f"Jacobian probe joint {i+1}")
        p1 = read_proprio(robot); q1a, _ = q_and_fingers(p1); x1, rot1 = tcp_pose(p1)
        dq = q1a[i]-q0[i]
        if abs(dq) > 1e-5:
            J[:3,i] = (x1-x0)/dq
            J[3:,i] = quat_rotvec(quat_mul(rot1, quat_inv(rot0)))/dq
        move_joints(robot, q0, steps, fingers[0], note=f"Return from Jacobian probe {i+1}")
    return J

if __name__ == "__main__":
    robot = connect()
    print(json.dumps({"spec": robot.spec(), "status": robot.status()}, indent=2))
